const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Eastern Canada region
  const easternCanada = ee.Geometry.Rectangle([-80, 45, -50, 55]);

  // 2. Get CO data for June 1, 2023
  const date1 = '2023-06-01';
  const col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(date1, '2023-06-02')
    .filterBounds(easternCanada)
    .select('CO_column_number_density');

  const size1 = col1.size().getInfo();
  console.log(`June 1 Images: ${size1}`);

  if (size1 === 0) {
    console.log('No data for June 1, 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get CO data for June 5, 2023
  const date2 = '2023-06-05';
  const col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(date2, '2023-06-06')
    .filterBounds(easternCanada)
    .select('CO_column_number_density');

  const size2 = col2.size().getInfo();
  console.log(`June 5 Images: ${size2}`);

  if (size2 === 0) {
    console.log('No data for June 5, 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process June 1 data
  const img1 = col1.mean();
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: easternCanada,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.CO_column_number_density_mean;
  const count1 = stats1.CO_column_number_density_count;

  console.log(`June 1: Mean CO = ${mean1}, Pixels = ${count1}`);

  if (count1 === 0 || count1 === null) {
    console.log('No valid pixels for June 1');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Process June 5 data
  const img2 = col2.mean();
  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: easternCanada,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mean2 = stats2.CO_column_number_density_mean;
  const count2 = stats2.CO_column_number_density_count;

  console.log(`June 5: Mean CO = ${mean2}, Pixels = ${count2}`);

  if (count2 === 0 || count2 === null) {
    console.log('No valid pixels for June 5');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Validate and compare
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log('Invalid calculation results');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Comparison: June 5 (${mean2.toFixed(6)}) vs June 1 (${mean1.toFixed(6)})`);

  if (mean2 > mean1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
